	};

	var options = {
		id : "popupTest",
		popupName : "팝업테스트",
		type :  "wframePopup",
		width : "560px",
		height : "400px",
		top :  "140px",
		left :  "500px",
		modal :  true,
		dataObject : _dataObj,
		alwaysOnTop :  false,
		useModalStack :  true,
		resizable :  true,
		useMaximize : false,
		className :  "",
		scrollbars : true,
		closeAction :"",
		popupUrl : "../popup"
	};



	$p.openPopup("popup_modal_userFilter_WESD-938_(WSQ-4919)_sub.xml" , options);
